-- 单表代码生成示例
DROP TABLE IF EXISTS dev_single_table_demo;
CREATE TABLE dev_single_table_demo (id_ varchar(64) NOT NULL COMMENT '主键ID', name_ varchar(128) NOT NULL COMMENT '姓名', age_ int COMMENT '年龄', weight_ double COMMENT '体重', birthday_ date COMMENT '生日', TENANT_ID_ varchar(64) COMMENT '租户', CREATED_BY_ID_ varchar(64) COMMENT '创建人ID', CREATED_BY_NAME_ varchar(64) COMMENT '创建人名称', CREATED_TIME_ datetime COMMENT '创建时间', DELFLAG_ varchar(1) COMMENT '逻辑删除标记', DISPLAY_ORDER_ int COMMENT '显示序号', MODIFIED_BY_ID_ varchar(64) COMMENT '修改人ID', MODIFIED_BY_NAME_ varchar(64) COMMENT '修改人名称', MODIFIED_TIME_ timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间', VERSION_ int COMMENT '版本', PRIMARY KEY (id_)) ENGINE=InnoDB DEFAULT CHARSET=utf8 DEFAULT COLLATE=utf8_general_ci COMMENT='单表代码生成演示';
-- 树表代码生成示例
DROP TABLE IF EXISTS dev_tree_table_demo;
CREATE TABLE dev_tree_table_demo (tree_table_demo_code_ varchar(64) NOT NULL COMMENT '编码', tree_table_demo_name_ varchar(128) COMMENT '名称', parent_id_ varchar(64) COMMENT '父节点ID', tree_table_demo_desc_ varchar(256) COMMENT '描述', TENANT_ID_ varchar(64) COMMENT '租户', CREATED_BY_ID_ varchar(64) COMMENT '创建人ID', CREATED_BY_NAME_ varchar(64) COMMENT '创建人名称', CREATED_TIME_ datetime COMMENT '创建时间', DELFLAG_ varchar(1) COMMENT '逻辑删除标记', DISPLAY_ORDER_ int COMMENT '显示序号', MODIFIED_BY_ID_ varchar(64) COMMENT '修改人ID', MODIFIED_BY_NAME_ varchar(64) COMMENT '修改人名称', MODIFIED_TIME_ timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间', VERSION_ int COMMENT '版本', PRIMARY KEY (tree_table_demo_code_)) ENGINE=InnoDB DEFAULT CHARSET=utf8 DEFAULT COLLATE=utf8_general_ci COMMENT='树形表代码生成演示';
