-- 仪表盘小组件示例
DROP TABLE IF EXISTS dev_widget_demo;
CREATE TABLE dev_widget_demo (id varchar(64) NOT NULL COMMENT '主键ID', prod_name varchar(128) NOT NULL COMMENT '产品名称', prod_price double NOT NULL COMMENT '产品价格', prod_cat varchar(1) NOT NULL COMMENT '产品分类', prod_score int NOT NULL COMMENT '产品评分', PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8 DEFAULT COLLATE=utf8_general_ci COMMENT='仪表盘小组件演示';

